// Enhanced session management for cross-server deployments
const SESSION_MANAGEMENT = {
    // Check for existing active session before creating new one
    checkExistingSession: async function (phone, email) {
        try {
            // Get or generate fingerprint to ensure we check for the correct browser session
            let fingerprint = this.getStoredSessionFingerprint();
            if (!fingerprint) {
                fingerprint = this.generateSessionFingerprint({ phone, email });
            }

            const response = await fetch(`${SERVER_BASE_URL}/website/chat/check-session`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    phone: phone,
                    email: email,
                    website: window.location.href,
                    session_fingerprint: fingerprint,
                    client_id: this.getClientId(),
                    website_origin: this.getWebsiteOrigin()
                })
            });

            if (response.ok) {
                const result = await response.json();
                return result;
            }
        } catch (error) {
            // Silently handle error
        }
        return null;
    },


    // Stable identifiers and helpers
    getClientId: function () {
        const KEY = 'abrus_chat_client_id';
        let id = localStorage.getItem(KEY);
        if (!id) {
            id = (crypto.randomUUID && crypto.randomUUID()) ||
                ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, c =>
                    (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16));
            localStorage.setItem(KEY, id);
        }
        return id;
    },

    getReconnectToken: function () {
        const KEY = 'abrus_chat_reconnect_token';
        let tok = localStorage.getItem(KEY);
        if (!tok) {
            tok = (crypto.randomUUID && crypto.randomUUID()) ||
                ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, c =>
                    (c ^ crypto.getRandomValues(new Uint8Array(1))[0] & 15 >> c / 4).toString(16));
            localStorage.setItem(KEY, tok);
        }
        return tok;
    },

    getWebsiteOrigin: function () {
        try {
            const u = new URL(window.location.href);
            return `${u.protocol}//${u.host}`;
        } catch (e) {
            return window.location.origin || '';
        }
    },

    buildIdempotencyKey: function (userInfo) {
        const canon = [
            this.getClientId(),
            this.getWebsiteOrigin(),
            (userInfo?.phone || '').trim().toLowerCase(),
            (userInfo?.email || '').trim().toLowerCase(),
        ].join('::');
        // Simple stable hash (fallback without subtle.digest to keep it sync)
        function hashStr(s) {
            let h = 0;
            for (let i = 0; i < s.length; i++) { h = ((h << 5) - h) + s.charCodeAt(i); h |= 0; }
            return ('00000000' + (h >>> 0).toString(16)).slice(-8);
        }
        return (window.crypto && window.crypto.subtle && window.TextEncoder)
            ? (function () {
                // Note: kept sync API for simplicity; if you have async, you can upgrade later.
                return canon; // backend can hash; we keep raw to avoid async refactor
            })()
            : canon;
    },
    // Generate unique session fingerprint
    generateSessionFingerprint: function (userInfo) {
        const fingerprint = {
            client_id: this.getClientId(),
            phone: userInfo?.phone || '',
            email: userInfo?.email || '',
            website_origin: this.getWebsiteOrigin(),
            userAgent: navigator.userAgent || ''
        };
        return btoa(JSON.stringify(fingerprint));
    },

    // Store session fingerprint
    storeSessionFingerprint: function (fingerprint) {
        localStorage.setItem('abrus_chat_session_fingerprint', fingerprint);
    },

    // Get stored session fingerprint
    getStoredSessionFingerprint: function () {
        return localStorage.getItem('abrus_chat_session_fingerprint');
    },

    // Clear session fingerprint
    clearSessionFingerprint: function () {
        localStorage.removeItem('abrus_chat_session_fingerprint');
    }
};

